import React,{useCallback,useEffect,useState}from"react";import AppShell from"../../components/AppShell";import{getQueue,subscribeToQueue}from"../../services/queueService";
export default function MyQueue({profile}){const[rows,setRows]=useState([]),[error,setError]=useState("");const load=useCallback(async()=>{try{setRows(await getQueue({ownerId:profile.id}))}catch(e){setError(e.message)}},[profile.id]);useEffect(()=>{load();const off=subscribeToQueue(load);return()=>off()},[load]);const active=rows.find(r=>r.status!=="Completed");return <AppShell profile={profile} title="My Queue">{error&&<div className="err">{error}</div>}{!active?<div className="card"><h2>No active queue</h2><p>Check in at the clinic reception when you arrive.</p></div>:<div className="queuecard"><p>Your queue number</p><strong>{active.queue_number}</strong><h3>{active.pet?.pet_name}</h3><p>{active.veterinarian?.full_name}</p><div className="grid"><span><b>{active.status}</b>Status</span><span><b>{active.clientsAhead}</b>Clients ahead</span><span><b>~{active.estimatedWaitMinutes} min</b>Estimated wait</span></div>{active.late_arrival&&<div className="warn">Late arrival recorded. Your place follows the active queue order.</div>}</div>}<style>{`.err,.warn{padding:13px;border-radius:12px;background:#fff0f0;color:#b34b4b}.queuecard{max-width:650px;margin:auto;text-align:center;background:#fff;padding:35px;border-radius:22px;box-shadow:0 10px 30px #d4eaf3}.queuecard>strong{font-size:60px;color:#318fbe}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin:24px 0}.grid span{background:#eff9fc;padding:14px;border-radius:14px}.grid b{display:block;color:#318fbe;margin-bottom:5px}@media(max-width:600px){.grid{grid-template-columns:1fr}}`}</style></AppShell>}
